import {PEOPLE,TOPICS,uid,baseState,newAttempt,summary,interactions,latestInteractions,insights,readyTicket,gates,canStage,canRelease,bumpRevision,createTicket} from './domain.js';
import {ScormRuntime} from './runtime.js';
import {session,login,logout,cloudRequest} from './cloud.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',book:'<path d="M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3zM12 6v15"/>',users:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 15a5 5 0 0 1 3 5"/>',chart:'<path d="M4 3v18h17M8 16v-4M13 16V8M18 16V5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5zM20 2v4M18 4h4"/>',code:'<path d="m7 7-5 5 5 5M17 7l5 5-5 5M14 3l-4 18"/>',rocket:'<path d="M13 4c3-2 6-2 8-1 1 6-4 12-10 13l-3-3c0-4 2-7 5-9zM8 9H4l-2 5h5M15 16v4l-5 2v-5M5 18l-2 3"/><circle cx="16" cy="7" r="1.5"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M19 12H5m6-6-6 6 6 6"/>',back:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',play:'<path d="m8 4 12 8-12 8z"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',shield:'<path d="m12 2 9 4v6c0 5-5 9-9 11-4-2-9-6-9-11V6zM8 12l3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',flag:'<path d="M5 21V3c5-3 8 4 14 1v10c-6 3-9-4-14-1"/>',cloud:'<path d="M6 18a5 5 0 1 1 0-10 7 7 0 0 1 13-1 5 5 0 0 1 0 11z"/>',logout:'<path d="M9 3H3v18h6M8 12h13m-5-5 5 5-5 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',refresh:'<path d="M20 8a8 8 0 1 0 0 8M20 3v5h-5"/>',file:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h6"/>'};
const icon=(n,c='')=>`<svg class="${c}" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||paths.info}</svg>`;
const btn=(label,action,kind='',extra='')=>`<button class="btn ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const pill=(text,kind='')=>`<span class="pill ${kind}">${text}</span>`;
const person=id=>PEOPLE.find(p=>p.id===id)||PEOPLE[0];
const course=id=>state.courses.find(c=>c.id===id);
const attemptFor=(cid,uid)=>state.attempts.filter(a=>a.courseId===cid&&a.userId===uid).sort((a,b)=>b.startedAt.localeCompare(a.startedAt))[0];
const fmtDate=x=>new Date(x).toLocaleDateString('he-IL',{day:'numeric',month:'short'});
const fmtTime=x=>new Date(x).toLocaleTimeString('he-IL',{hour:'2-digit',minute:'2-digit'});
const duration=ms=>`${Math.floor(ms/60000)}:${String(Math.floor(ms/1000)%60).padStart(2,'0')}`;
const statusLabel=s=>s==='completed'?'התוכן הושלם':s==='active'?'בתהליך':'טרם התחיל';
let state=baseState(),questionLabels={},catalog=[],localMode=false,cloudStatus='connecting',saveTimer=null,saving=false,dirty=0,saved=0,runtime=null,activeAttempt=null,activeCourse=null,renderTimer=null,quizNotice=false,selectedReport=null,busy=false,route='dashboard';
const cacheKey=()=>`ofek-state-${localMode?'local':session?.user?.id||'none'}`;
function toast(t,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=t;$('#toasts').append(el);setTimeout(()=>el.remove(),4500)}
function audit(text,type='system'){state.audit.unshift({id:uid(),at:new Date().toISOString(),text,type});state.audit=state.audit.slice(0,120)}
function updateSync(){const e=$('#sync-state');if(e)e.innerHTML=localMode?'שמירה במכשיר הזה':cloudStatus==='saved'?'נשמר ב־Supabase':cloudStatus==='error'?'שמירה בענן נכשלה':cloudStatus==='saving'?'שומר בענן…':'מתחבר לענן…';const b=$('#sync-dot');if(b)b.className='pill '+(cloudStatus==='error'?'red':'green')}
function persist(){dirty++;try{localStorage.setItem(cacheKey(),JSON.stringify({state,pending:!localMode,at:new Date().toISOString()}))}catch{toast('האחסון המקומי מלא. נסו לייצא את הנתונים.',true)}if(localMode){cloudStatus='saved';updateSync();return}cloudStatus='saving';updateSync();clearTimeout(saveTimer);saveTimer=setTimeout(flush,500)}
async function flush(){if(localMode||saving||saved===dirty)return;const revision=dirty;saving=true;try{await cloudRequest('POST',{state:structuredClone(state)});saved=revision;cloudStatus='saved';localStorage.setItem(cacheKey(),JSON.stringify({state,pending:saved!==dirty,at:new Date().toISOString()}))}catch(e){cloudStatus='error';toast(e.message,true)}finally{saving=false;updateSync();if(saved<dirty&&cloudStatus!=='error')setTimeout(flush,50)}}
function modal(title,description,body,actions='',wide=false){const m=$('#modal');m.className=wide?'wide':'';m.innerHTML=`<div class="modal"><div class="modal-head"><div><h2>${title}</h2><p>${description}</p></div><button class="close" data-action="close-modal" aria-label="סגירה">${icon('close')}</button></div>${body}${actions?`<div class="modal-actions">${actions}</div>`:''}</div>`;if(!m.open)m.showModal()}
const closeModal=()=>$('#modal').close();
function head(title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">אופק / סביבת למידה</div><h1>${title}</h1><p>${sub}</p></div><div class="row">${actions}</div></div>`}
const empty=(title,desc,action='')=>`<div class="empty"><span class="empty-symbol">${icon('book','large')}</span><h3>${title}</h3><p>${desc}</p>${action}</div>`;
const stat=(label,value,note,ic)=>`<div class="stat"><div class="row"><span>${label}</span><span class="stat-icon">${icon(ic)}</span></div><strong>${value}</strong><small>${note}</small></div>`;
const progress=s=>s.progress===null?'<span class="muted">לא דווח אחוז</span>':`<div class="progress-line"><div class="progress"><i style="width:${Math.max(0,Math.min(100,s.progress*100))}%"></i></div><bdi>${Math.round(s.progress*100)}%</bdi></div>`;
function navItems(){return state.role==='student'?[['learn','book','הלמידה שלי'],['my-results','chart','התוצאות שלי'],['guide','play','מסלול הפגישה']]:[['dashboard','home','תמונת מצב'],['library','book','ספריית לומדות'],['assignments','users','משימות לתלמידים'],['reports','chart','דוחות למידה'],['insights','spark','תובנות למורה'],['divider','','תהליך הפיתוח'],['development','code','משימות וסקירות'],['pipeline','rocket','בדיקות ופריסה'],['environments','settings','סביבות ופיצ׳רים'],['guide','play','מסלול הפגישה']]}
const routeTitles={dashboard:'תמונת מצב',library:'ספריית לומדות',assignments:'משימות לתלמידים',reports:'דוחות למידה',insights:'תובנות למורה',development:'משימות וסקירות',pipeline:'בדיקות ופריסה',environments:'סביבות ופיצ׳רים',guide:'מסלול הפגישה',learn:'הלמידה שלי','my-results':'התוצאות שלי',player:'לומדה פעילה'};
function shell(content,player=false){const u=state.role==='student'?person(state.learner):{name:'מיכל רז',initials:'מר'};$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">א</div><div><div class="brand-name">אופק</div><small>כל לומד. והדרך שלו.</small></div></div><div class="nav-label">סביבת ${state.role==='student'?'התלמיד':'הצוות'}</div><nav>${navItems().map(([id,ic,label])=>id==='divider'?`<div class="nav-label">${label}</div>`:`<a href="#${id}" class="nav-item ${route===id?'active':''}" title="${label}" ${route===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></a>`).join('')}</nav><div class="sidebar-bottom"><div class="user-card"><span class="avatar">${u.initials}</span><div>${u.name}<small>${state.role==='student'?person(state.learner).className:'רכזת פדגוגית · בית ספר לדוגמה'}</small></div></div></div></aside><div class="workspace"><header class="topbar"><div class="crumb"><button class="icon-button mobile-menu" data-action="mobile-nav" aria-label="ניווט">${icon('menu')}</button><span>בית ספר אופק</span><span>/</span><b>${routeTitles[route]||'למידה'}</b></div><div class="top-actions"><span class="pill green" id="sync-dot">${icon('cloud')}<span id="sync-state"></span></span><select class="role-select" id="role" aria-label="מעבר בין תצוגות"><option value="teacher" ${state.role==='teacher'?'selected':''}>תצוגת מורה ומנהל</option>${PEOPLE.map(p=>`<option value="${p.id}" ${state.role==='student'&&state.learner===p.id?'selected':''}>תלמיד: ${p.name}</option>`).join('')}</select><button class="icon-button" data-action="about" aria-label="על סביבת ההדגמה">${icon('info')}</button><button class="icon-button" data-action="logout" aria-label="יציאה מהחשבון">${icon('logout')}</button></div></header><main class="${player?'player-workspace':'main'}">${content}</main></div>`;updateSync();$('#role').onchange=e=>switchRole(e.target.value)}
function goto(id){if(route===id){render();return}location.hash=id}
function switchRole(value){stopCourse();if(value==='teacher')state.role='teacher';else{state.role='student';state.learner=value}persist();goto(value==='teacher'?'dashboard':'learn')}
function allSummaries(){return state.assignments.map(a=>({assignment:a,course:course(a.courseId),attempt:attemptFor(a.courseId,a.userId),user:person(a.userId)})).filter(x=>x.course).map(x=>({...x,summary:summary(x.attempt,x.course)}))}
function learnerTable(rows,limit=999){return rows.length?`<div class="table-wrap"><table><thead><tr><th>תלמיד</th><th>לומדה</th><th>מצב</th><th>ציון</th><th>התקדמות מדווחת</th><th></th></tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr><td><div class="cell-person"><span class="avatar" style="background:${r.user.color}">${r.user.initials}</span><span>${r.user.name}<small>${r.user.className}</small></span></div></td><td>${esc(r.course.title.replace('יסודות הגולף · ','גולף · '))}</td><td>${pill(statusLabel(r.summary.status),r.summary.status==='completed'?'green':r.summary.status==='active'?'orange':'')}</td><td><bdi>${r.summary.score??'—'}</bdi></td><td>${progress(r.summary)}</td><td>${btn('דוח','report','secondary small',`data-user="${r.user.id}" data-course="${r.course.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('עוד אין משימות משויכות','טוענים לומדה מוכנה ומשייכים אותה לתלמידים כדי להתחיל לראות נתונים.',btn('לספריית הלומדות','nav-library'))}
function dashboard(){const rows=allSummaries(),started=rows.filter(x=>x.attempt),scores=rows.map(x=>x.summary.score).filter(x=>x!==null),completed=rows.filter(x=>x.summary.status==='completed'),attention=rows.filter(x=>x.summary.wrong>0);return head('בוקר טוב, מיכל','כל מה שצריך לדעת על הלמידה, במקום אחד.',btn(icon('plus')+'משימה חדשה','assign'))+`<div class="stats">${stat('תלמידים ששויכו',new Set(rows.map(x=>x.user.id)).size,'מתוך 4 תלמידי הדוגמה','users')}${stat('ניסיונות שהתחילו',started.length,'הפעלות בפועל של הלומדות','play')}${stat('ציון ממוצע',scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):'—',scores.length?`${scores.length} ניסיונות עם ציון מדווח`:'יופיע אחרי הגשת מבחן','chart')}${stat('תוכן שהושלם',completed.length,'כפי שדווח על ידי הלומדה','check')}</div>${!state.courses.length?`<div class="hero"><div><h2>מתחילים בלומדה שכבר מוכנה.</h2><p>טוענים חבילת לימוד, בוחרים תלמידים ורואים איך הפעולות שלהם הופכות לדוח שימושי למורה.</p>${btn('טעינת לומדה מוכנה '+icon('arrow'),'import-modal')}</div><div class="hero-icon">${icon('book')}</div></div>`:''}<div class="columns"><div class="stack"><section class="panel"><div class="panel-title"><div><h3>הלמידה בכיתה</h3><p>מצב עדכני מהלומדות ששויכו</p></div><a href="#reports" class="inline-link">כל הדוחות</a></div>${learnerTable(rows,6)}</section><section class="panel"><div class="panel-title"><h3>פעילות אחרונה</h3>${pill('פעולות אמיתיות במערכת','green')}</div>${state.audit.length?`<div class="timeline">${state.audit.filter(x=>x.type==='learning').slice(0,5).map(x=>`<div class="timeline-item"><i class="timeline-dot"></i><div><p>${esc(x.text)}</p><small>${fmtDate(x.at)} · ${fmtTime(x.at)}</small></div></div>`).join('')||'<p class="empty-mini">הפעילות תופיע עם תחילת הלמידה</p>'}</div>`:'<p class="empty-mini">עוד לא בוצעו פעולות למידה</p>'}</section></div><div class="stack"><section class="panel"><div class="panel-title"><div><h3>מבט פדגוגי</h3><p>תובנות מחושבות, עם ראיות</p></div>${icon('spark')}</div>${attention.length?attention.slice(0,3).map(x=>`<div class="insight attention"><h4>${x.user.name}</h4><p>${x.summary.wrong} תשובות שגויות מתוך ${x.summary.questions} שאלות מדווחות.</p><button class="inline-link" data-action="report" data-user="${x.user.id}" data-course="${x.course.id}">לבדיקת התשובות</button></div>`).join(''):`<div class="insight info"><h4>${icon('info')}ממתינים לנתוני למידה</h4><p>לא מוצגים קשיים או המלצות לפני שמתקבלים דיווחים אמיתיים מהלומדה.</p></div>`}<p class="export-note">התובנות מחושבות לפי כללים. לא הופעל כאן שירות בינה מלאכותית.</p></section><section class="panel pad"><div class="row gap-lg">${icon('shield','large')}<div><h3>לומדה, נתון, משמעות.</h3><p class="note">כל ציון ותשובה בדוח ניתנים לבדיקה מול הדיווח המקורי.</p></div></div></section></div></div>`}
function courseCard(c,learner=false){const a=attemptFor(c.id,state.learner),s=summary(a,c);return `<article class="course-card"><div class="course-art ${c.version==='1.2'?'basic':''}">${pill('לומדה מוכנה · '+c.language)}<span class="course-symbol" aria-hidden="true">G.</span></div><div class="course-card-body"><div class="badge-line">${pill('SCORM '+c.version,'green')}${pill(c.hasInteractions?'כולל תשובות לשאלות':'דיווח כללי','blue')}</div><h3>${esc(c.title)}</h3><p>${learner?'לומדים את כללי המשחק, מתקדמים בקצב אישי ובודקים את הידע במבחן.':'חבילה מקורית של Rustici. התוכן והדיווח מגיעים מהלומדה עצמה.'}</p><div class="course-meta"><span>15 מסכי תוכן ומבחן</span><span>כ־${Math.round(c.bytes/1024)} KB</span></div>${learner?`<div class="row between" style="margin-bottom:15px">${pill(statusLabel(s.status),s.status==='completed'?'green':'orange')}<span class="note">ציון: ${s.score??'טרם התקבל'}</span></div>${btn((a?'המשך למידה':'התחלת למידה')+' '+icon('play'),'launch','',`data-course="${c.id}"`)}`:`${btn('שיוך לתלמידים '+icon('users'),'assign','',`data-course="${c.id}"`)}<button class="inline-link" style="margin-top:10px" data-action="course-info" data-course="${c.id}">מקור הלומדה ומה היא מדווחת</button>`}</div></article>`}
function library(){return head('ספריית הלומדות','התוכן כבר קיים. כאן טוענים, בודקים ומשייכים אותו לתלמידים.',btn(icon('upload')+'טעינת לומדה','import-modal'))+(state.courses.length?`<div class="course-grid">${state.courses.map(c=>courseCard(c)).join('')}</div>`:`<div class="library-empty">${empty('הלומדה הראשונה שלכם מחכה','אפשר לטעון את חבילת הדוגמה מהאינטרנט או להעלות את קובץ הדוגמה שהורדתם.',btn('בחירת לומדה מוכנה','import-modal'))}</div>`)+`<div class="notice info">${icon('info')}<p><b>SCORM — תקן להעברת דיווחי למידה.</b> החבילה המפורטת מדווחת תשובות ומיומנויות. החבילה הבסיסית מדווחת ציון ומצב בלבד. זו הדגמת חיבור לשתי חבילות שנבדקו, ולא אישור תאימות לכל לומדת Storyline.</p></div>`}
function assignments(){const rows=allSummaries();return head('משימות לתלמידים','שיוך אישי או לכיתה, עם מעקב אחרי כל תלמיד.',btn(icon('plus')+'שיוך חדש','assign'))+`<section class="panel"><div class="panel-title"><h3>${rows.length} שיוכים פעילים</h3>${pill('נתוני תלמידים בדיוניים')}</div>${learnerTable(rows)}</section>`}
function learn(){const u=person(state.learner),assigned=state.assignments.filter(a=>a.userId===u.id),courses=assigned.map(a=>course(a.courseId)).filter(Boolean);return head(`היי ${u.name.split(' ')[0]}, מה לומדים היום?`,'המשימות שלך מחכות. אפשר לצאת ולחזור לאותו ניסיון למידה.')+`<div class="walkthrough"><div><b>הלמידה שלך נשמרת בדרך.</b><p>התקדמות, תשובות וציונים מתקבלים ישירות מהלומדה.</p></div>${icon('book','large')}</div>`+(courses.length?`<div class="course-grid">${courses.map(c=>courseCard(c,true)).join('')}</div>`:`<section class="panel">${empty('עדיין לא שויכה לך משימה','עוברים לתצוגת המורה, טוענים לומדה ומשייכים אותה לתלמיד הזה.',btn('מעבר לתצוגת מורה','teacher','secondary'))}</section>`)}
function reports(){const rows=allSummaries().filter(x=>state.role!=='student'||x.user.id===state.learner);return head(state.role==='student'?'התוצאות שלי':'דוחות למידה','הנתונים שהלומדה דיווחה — בלי השלמת מידע חסר.',btn(icon('download')+'ייצוא CSV','export-csv','secondary'))+`<section class="panel"><div class="panel-title"><h3>תוצאות לפי תלמיד ומשימה</h3>${pill('דיווחי לומדה','green')}</div>${learnerTable(rows)}</section><div class="notice info">${icon('info')}<p>״התוכן הושלם״ אינו בהכרח ״המבחן עבר״. מציגים בנפרד השלמה, ציון והצלחה בהתאם לדיווחי החבילה.</p></div>`}
function insightsPage(){const rows=allSummaries().filter(x=>x.attempt);return head('מה אפשר ללמוד מהנתונים?','כל תובנה נשענת על תשובות מדווחות. ההחלטה הפדגוגית נשארת אצל המורה.')+`<div class="notice info">${icon('spark')}<p>התובנות כאן מחושבות לפי כללים שקופים. שירות בינה מלאכותית לשיחה או לניסוח נוסף עדיין אינו מחובר.</p></div>`+(rows.length?`<div class="course-grid">${rows.map(r=>`<section class="panel"><div class="panel-title"><div><h3>${r.user.name}</h3><p>${r.course.title}</p></div>${icon('spark')}</div>${insights(r.attempt,r.course).map(insightHtml).join('')}<div style="padding:0 20px 20px">${btn('לראיות ולתשובות','report','secondary small',`data-user="${r.user.id}" data-course="${r.course.id}"`)}</div></section>`).join('')}</div>`:`<section class="panel">${empty('קודם לומדים, אחר כך מסיקים','כאן יופיעו המלצות אחרי קבלת תוצאות מהלומדה.')}</section>`)}
function answerLabel(q,value){const item=questionLabels[q.id];if(item?.type==='choice'&&item.choices?.[Number(value)]!==undefined)return item.choices[Number(value)];return value==='true'?'נכון':value==='false'?'לא נכון':value}
const insightHtml=i=>`<div class="insight ${i.kind}"><h4>${icon(i.kind==='attention'?'flag':'info')}${esc(i.title)}</h4><p>${esc(i.body)}</p></div>`;
function importModal(){modal('טוענים לומדה מוכנה','דוגמאות רשמיות של Rustici, שהורדו מהאתר המקורי ונבדקו להפעלה כאן.',`<div class="stack">${catalog.map(c=>`<div class="import-option"><h3>${esc(c.title)}</h3><p>${c.hasInteractions?'כולל תוצאה, התקדמות ופירוט תשובות לכל שאלה.':'כולל תוצאה ומצב השלמה, ללא פירוט תשובות.'}</p><div class="row">${btn(state.courses.some(x=>x.id===c.id)?'כבר בספרייה':'טעינת החבילה','import','',`data-course="${c.id}" ${state.courses.some(x=>x.id===c.id)?'disabled':''}`)}<a class="inline-link" href="${c.file}" download>הורדת קובץ הדוגמה</a></div></div>`).join('')}<label class="dropzone">${icon('upload')}<b>או העלאת קובץ דוגמה מהמחשב</b><span>בגרסה זו נתמכות שתי החבילות שלמעלה בלבד</span><input type="file" id="package-file" accept=".zip"></label></div>`)}
async function importCourse(id,file){if(busy)return;busy=true;try{toast('בודק את חבילת הלומדה…');const c=catalog.find(x=>x.id===id);const bytes=file?await file.arrayBuffer():await (await fetch(c.file)).arrayBuffer();const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');const matched=catalog.find(x=>x.sha256===hash);if(!matched)throw new Error('החבילה אינה אחת משתי הדוגמאות שנבדקו. לא נטען קוד שלא נבדק.');if(state.courses.some(x=>x.id===matched.id))throw new Error('הלומדה כבר קיימת בספרייה');state.courses.push({...matched,importedAt:new Date().toISOString()});audit(`נטענה לומדה: ${matched.title}`,'learning');persist();closeModal();goto('library');toast('הלומדה מוכנה לשיוך לתלמידים')}catch(e){toast(e.message,true)}finally{busy=false}}
function assignModal(cid){if(!state.courses.length){importModal();return}modal('למי משייכים את הלומדה?','כל תלמיד יקבל ניסיון למידה נפרד, עם התקדמות ותוצאות משלו.',`<form id="assignment-form"><label class="field">לומדה<select name="course">${state.courses.map(c=>`<option value="${c.id}" ${c.id===cid?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label><div class="field"><span>תלמידים</span>${PEOPLE.map(p=>`<label class="checkbox-row"><input type="checkbox" name="student" value="${p.id}" checked><span>${p.name} · ${p.className}</span></label>`).join('')}</div><label class="field">מועד לביצוע<input type="date" name="due" value="${new Date(Date.now()+7*86400000).toISOString().slice(0,10)}" required></label><button class="btn" type="submit">שמירת השיוך</button></form>`)}
function reportModal(cid,user){const c=course(cid),a=attemptFor(cid,user);if(!c)return;selectedReport=a;const s=summary(a,c),rows=latestInteractions(a);modal(`הדוח של ${person(user).name}`,c.title,`<div class="stats">${stat('מצב',statusLabel(s.status),'לפי דיווח הלומדה','book')}${stat('ציון',s.score??'—','הציון הגולמי שהתקבל','chart')}${stat('שאלות מדווחות',rows.length,'אין השלמה של נתונים חסרים','check')}${stat('זמן הפעלה',duration(a?.elapsedMs||0),'זמן במעטפת, עד היציאה','clock')}</div><div class="notice info"><p>הצלחה במבחן: <b>${s.success==='passed'?'עבר':s.success==='failed'?'לא עבר':'טרם נקבעה'}</b>${s.derived?` · מחושב לפי ציון מדווח וסף מעבר ${c.mastery}% שמוגדר בחבילה.`:' · בהתאם לדיווח מהלומדה.'}</p></div>${insights(a,c).map(insightHtml).join('')}${rows.length?`<div class="table-wrap"><table class="question-table"><thead><tr><th>שאלה מהלומדה</th><th>תשובת התלמיד</th><th>התשובה המצופה</th><th>תוצאה</th></tr></thead><tbody>${rows.map(q=>`<tr><td dir="auto">${esc(q.description)}<small>${esc(TOPICS[q.objective]||q.objective)}</small></td><td dir="auto">${esc(answerLabel(q,q.response))}</td><td dir="auto">${esc(answerLabel(q,q.correct))}</td><td>${pill(q.result==='correct'?'נכון':['incorrect','wrong'].includes(q.result)?'שגוי':esc(q.result),q.result==='correct'?'green':'orange')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-mini">לא התקבלו תשובות פרטניות מהלומדה.</p>'}${a?`<details><summary>בדיקת הדיווח המקורי</summary><pre class="raw-data" dir="ltr">${esc(JSON.stringify(a.data,null,2))}</pre></details>`:''}`,a?btn('הורדת נתוני הניסיון','export-attempt','secondary'):'',true)}
function launch(cid){const c=catalog.find(x=>x.id===cid);if(!c||!state.assignments.some(x=>x.courseId===cid&&x.userId===state.learner)){toast('יש לשייך את הלומדה לתלמיד לפני הפעלה',true);return}stopCourse();activeCourse=c;activeAttempt=attemptFor(cid,state.learner);if(!activeAttempt){activeAttempt=newAttempt(c,person(state.learner));state.attempts.push(activeAttempt)}else activeAttempt.data[c.version==='1.2'?'cmi.core.entry':'cmi.entry']='resume';runtime=new ScormRuntime(activeAttempt,c,{onChange:()=>{persist();clearTimeout(renderTimer);renderTimer=setTimeout(updateLive,100)},onExit:()=>setTimeout(()=>{stopCourse();goto('learn')},0)});window.API=c.version==='1.2'?runtime.api:undefined;window.API_1484_11=c.version==='2004'?runtime.api:undefined;audit(`${person(state.learner).name} פתח/ה את ${c.title}`,'learning');route='player';history.replaceState(null,'','#player');shell(`<div class="player-heading"><div><h2>${esc(c.title)}</h2><p>${person(state.learner).name} · לומדה חיצונית מוכנה באנגלית</p></div>${btn('שמירה ויציאה','exit-course','secondary')}</div><div class="player-layout"><section class="player-main"><div class="player-toolbar"><span class="pill green">התוכן המקורי של Rustici</span><div class="row">${btn('הקודם','course-prev','secondary small')}${btn('הבא','course-next','secondary small')}${btn('מעבר למבחן','course-quiz','small')}</div></div><iframe title="לומדת הגולף המקורית" class="player-frame" id="course-frame" sandbox="allow-scripts allow-same-origin allow-modals allow-forms" src="${c.launch}"></iframe></section><aside class="player-side"><div class="panel-title"><div><h3>מה המערכת קולטת עכשיו?</h3><p>הדיווח מגיע מהלומדה עצמה</p></div></div><div id="live-data"></div><div class="notice info"><p>SCORM הוא תקן דיווח בין לומדה למערכת. אין כאן ניתוח וידאו או ניחוש תשובות.</p></div><div class="panel-title"><h3>דיווחים אחרונים</h3></div><div id="live-events"></div></aside></div>`,true);persist();updateLive()}
function updateLive(){if(!activeAttempt||!$('#live-data'))return;const s=summary(activeAttempt,activeCourse);$('#live-data').innerHTML=`<div class="live-fields"><div><span>מצב</span><b>${statusLabel(s.status)}</b></div><div><span>ציון</span><b>${s.score??'טרם התקבל'}</b></div><div><span>שאלות</span><b>${s.questions}</b></div><div><span>מסך שמור</span><b>${s.location!==''&&s.location!==null?Number(s.location)+1:'—'}</b></div></div>${progress(s)}${s.status==='completed'&&s.score===null?'<p class="note">הגעה למבחן מסמנת השלמת תוכן בחבילה הזו. ציון יופיע רק אחרי הגשת תשובות.</p>':''}`;$('#live-events').innerHTML=`<div class="event-list">${activeAttempt.events.slice(-8).reverse().map(e=>`<div class="event"><small>${fmtTime(e.at)}</small><code dir="ltr">${esc(e.key||e.type)}</code><span dir="auto">${esc(String(e.value??'').slice(0,130))}</span></div>`).join('')}</div>`}
function stopCourse(){if(!runtime)return;try{$('#course-frame')?.contentWindow.doUnload(false)}catch{}runtime.close();runtime=null;window.API=undefined;window.API_1484_11=undefined;if(activeAttempt)audit(`נשמר ניסיון הלמידה של ${person(activeAttempt.userId).name}`,'learning');activeAttempt=null;activeCourse=null;persist()}
const external=(url,text)=>`<a class="inline-link" href="${url}" target="_blank" rel="noopener noreferrer">${text} ↗</a>`;
const simNotice=()=>`<div class="notice info">${icon('info')}<p><b>מעבדת תהליך — הדמיה אינטראקטיבית.</b> הכפתורים כאן מדגימים חסימות ואישורים; הם לא מבצעים סקירת קוד, בדיקות או פריסה אמיתית. הקישורים למעלה מובילים לכלים האמיתיים.</p></div>`;
function integrationBar(){return `<section class="panel pad"><div class="row between wrap"><div><b>הפרויקט האמיתי</b><p class="note">משימות Jira נוצרו. קוד, בדיקות וסקירות נבדקים ב־GitHub.</p></div><div class="row wrap">${external('https://wiseapps.atlassian.net/browse/TES-58','Jira · משימות ההדגמה')}${external('https://github.com/khalidzoabi1993/ofek-lms-demo','GitHub · הקוד')}${external('https://github.com/khalidzoabi1993/ofek-lms-demo/actions','GitHub Actions · הרצות')}${external('https://github.com/khalidzoabi1993/ofek-lms-demo/pulls','CodeRabbit · בקשות סקירה')}</div></div></section>`}
const selectedTicket=()=>state.tickets.find(t=>t.id===state.selectedTicket)||state.tickets[0];
function development(){return head('משימה ברורה לפני שכותבים קוד','מגדירים מה צריך לקרות ואיך נבדוק שזה עובד.',btn('יצירת טיקט לדוגמה','new-ticket'))+integrationBar()+simNotice()+`<div class="kanban">${[['draft','הגדרת המשימה'],['development','פיתוח וסקירה'],['staging','בדיקה ידנית'],['done','שוחרר']].map(([status,title])=>`<section class="kanban-column"><h3>${title} <span>${state.tickets.filter(t=>t.status===status).length}</span></h3>${state.tickets.filter(t=>t.status===status).map(t=>`<button class="ticket" data-action="ticket" data-id="${t.id}"><small>${t.id} · גרסה ${t.revision}</small><h4>${esc(t.title||'משימה חדשה')}</h4><p>${esc(t.owner)}</p>${pill(status==='draft'?'טרם מוכן לפיתוח':status==='done'?'הסתיים':'בתהליך',status==='done'?'green':'orange')}</button>`).join('')||'<p class="empty-mini">אין משימות בשלב הזה</p>'}</section>`).join('')}</div><div class="notice"><p><b>CodeRabbit נשאר במסלול הזמין בחינם.</b> אם המכסה הסתיימה, לא מתבצע שדרוג. הסקירה האוטומטית תישאר ממתינה ולא תוצג כאישור. אישור אנושי נדרש בנפרד.</p></div>`}
function ticketModal(id){const t=state.tickets.find(x=>x.id===id);if(!t)return;state.selectedTicket=id;modal(`${t.id} · הגדרת משימה`,'טיקט מלא כולל תוצאה רצויה, תנאי קבלה ותוכניות בדיקה.',`<form id="ticket-form" data-id="${t.id}">${[['title','שם המשימה'],['description','מה צריך לבנות ולמה'],['acceptance','תנאי קבלה — מה יוכיח שהמשימה הושלמה'],['autoPlan','מה ייבדק אוטומטית'],['manualPlan','מה ייבדק ידנית']].map(([k,label])=>`<label class="field">${label}<textarea name="${k}" required rows="${k==='title'?1:2}">${esc(t[k])}</textarea></label>`).join('')}<div class="form-grid">${[['owner','אחראי פיתוח'],['tester','אחראי בדיקה ידנית']].map(([k,l])=>`<label class="field">${l}<input name="${k}" value="${esc(t[k])}" required></label>`).join('')}</div><div class="row">${btn('מילוי דוגמת משימה','fill-ticket','secondary',`data-id="${t.id}"`)}<button class="btn" type="submit">שמירה והעברה לפיתוח</button></div></form>`)}
function pipeline(){const t=selectedTicket();return head('איכות היא תנאי למעבר','גם קוד שנכתב בעזרת בינה מלאכותית צריך לעבור בדיקה.')+integrationBar()+simNotice()+(t?`<label class="field">משימה לבדיקה<select id="pipeline-ticket">${state.tickets.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.id} · ${esc(x.title||'טיוטה')}</option>`).join('')}</select></label><section class="panel pad"><div class="row between"><h2>${esc(t.title||'משימה שלא הוגדרה')} · גרסה ${t.revision}</h2>${pill('הדמיה בלבד','purple')}</div><div class="gates">${gates(t).map(g=>`<div class="gate ${g.ok?'passed':''}">${icon(g.ok?'check':'clock')}<b>${g.label}</b><small>${g.ok?'עבר':'ממתין / חסום'}</small></div>`).join('')}</div><div class="row wrap">${btn('1 · סקירה מוצאת תקלה','sim-review','secondary')}${btn('2 · תיקון הקוד','sim-fix','secondary')}${btn('3 · סקירה חוזרת ואישור עמית','sim-approve','secondary')}${btn('4 · הרצת בדיקות','sim-tests','secondary')}${btn('בדיקת חסימה: כיסוי 89%','sim-low','secondary')}${btn('שינוי קוד אחרי אישור','sim-change','secondary')}</div><p class="note">כל שינוי בקוד מבטל אישורים קודמים. כיסוי מתחת ל־90% חוסם מעבר, גם אם הבדיקות עצמן עברו.</p>${t.coverage?`<div class="table-wrap"><table><thead><tr><th>מדד בדוגמה</th><th>ממשק המשתמש</th><th>קוד השרת</th></tr></thead><tbody>${['lines','branches','functions'].map((m,i)=>`<tr><td>${['שורות קוד','מסלולי החלטה','פונקציות'][i]}</td><td>${t.coverage.frontend[m]}%</td><td>${t.coverage.server[m]}%</td></tr>`).join('')}</tbody></table></div>`:''}</section><div class="columns equal"><section class="panel pad"><h3>סביבת בדיקות</h3><p>רק אחרי שכל הבדיקות והסקירות עברו.</p>${btn('פריסה לסביבת בדיקות','sim-stage','',canStage(t)?'':'disabled')}<p class="note">גרסה שנפרסה: ${t.stagedRevision??'טרם נפרסה'}</p>${btn('אישור בדיקה ידנית','sim-manual','secondary',t.stagedRevision===t.revision?'':'disabled')}</section><section class="panel pad"><h3>סביבת המשתמשים</h3><p>נדרש אישור ידני ואישור שחרור לגרסה הנוכחית.</p>${btn('אישור שחרור','sim-release-approve','secondary',t.manual==='passed'?'':'disabled')}${btn('פריסה למשתמשים','sim-release','',canRelease(t)?'':'disabled')}</section></div><section class="panel pad"><h3>יומן התהליך המדומה</h3><div class="run-console">${state.runs.slice(0,10).map(r=>`<p><span>${fmtTime(r.at)}</span> ${esc(r.text)}</p>`).join('')||'ממתין לפעולה הראשונה'}</div></section>`:`<section class="panel">${empty('מתחילים בטיקט','אין פיתוח לפני הגדרת המשימה.',btn('יצירת משימה לדוגמה','new-ticket'))}</section>`)}
function environments(){return head('שליטה בסביבות וביכולות','תצוגה של תהליך ניהול השחרורים המתוכנן.')+simNotice()+`<div class="course-grid">${[['development','פיתוח','כאן עובדים על שינויים'],['staging','בדיקות','כאן בודקים לפני שחרור'],['production','משתמשים','כאן נמצאת הגרסה שאושרה']].map(([k,n,d])=>`<section class="panel pad"><div class="row between"><h3>${n}</h3>${pill('סביבה מדומה')}</div><p>${d}</p><bdi class="version">${state.environments[k]}</bdi>${[['teacherSummary','סיכום למורה'],['studentHelp','עזרה לתלמיד']].map(([f,l])=>`<label class="toggle-row"><span>${l}</span><input type="checkbox" data-flag="${f}" data-env="${k}" ${state.flags[f][k]?'checked':''} role="switch" aria-label="${l} בסביבת ${n}"></label>`).join('')}</section>`).join('')}</div><section class="panel pad"><h3>מה אמיתי כעת?</h3><p>למערכת ההדגמה יש בסיס נתונים ופונקציית שרת אמיתיים ב־Supabase. שלוש הסביבות והמתגים שמעל מדגימים את תהליך העבודה ואינם משנים שירותי ענן.</p>${external('https://supabase.com/dashboard/project/nnbdbabmsqnecnmnvleh','פתיחת פרויקט Supabase')}</section><section class="panel pad"><h3>יומן שינויים</h3>${state.audit.filter(a=>a.type==='system').slice(0,10).map(a=>`<p class="note">${fmtTime(a.at)} · ${esc(a.text)}</p>`).join('')||'<p>עדיין אין שינויים</p>'}</section>`}
function guide(){return head('מציגים מערכת עובדת, צעד אחר צעד','מסלול קצר לפגישה. אפשר לעצור בכל שלב ולראות מה נשמר.')+`<div class="guide-grid">${[['01','טוענים תוכן קיים','בספרייה בוחרים את הלומדה עם הדיווח המפורט. המערכת מאמתת את החבילה.','library'],['02','משייכים לתלמידים','המורה בוחר מי יקבל את המשימה. לכל תלמיד נשמר ניסיון נפרד.','assignments'],['03','לומדים ועונים','עוברים לתצוגת נועה בתפריט העליון, מפעילים את הלומדה ועונים על המבחן.','learn'],['04','מבינים את התוצאה','חוזרים לתצוגת המורה ורואים ציון, תשובות ותובנות עם ראיות.','reports'],['05','מציגים תהליך פיתוח','פותחים את משימות Jira האמיתיות, ואחר כך מדגימים חסימות ואישורים במעבדה.','development'],['06','מראים את שערי האיכות','בדיקה אוטומטית, סקירה, כיסוי, בדיקה ידנית ואישור שחרור.','pipeline']].map(([n,t,d,r])=>`<article class="panel pad"><span class="step-number">${n}</span><h3>${t}</h3><p>${d}</p>${btn('לשלב הזה','guide-nav','secondary',`data-route="${r}"`)}</article>`).join('')}</div><section class="panel pad"><h3>מה חשוב להגיד לצוות?</h3><p>הלומדה מדווחת נתונים; אנחנו שומרים, מציגים ומחשבים מהם תובנות. הדוגמה אינה יוצרת תוכן. Supabase מטפל בנתונים ובהזדהות. הבדיקות והסקירות מגינות על תהליך הפיתוח.</p><p>הדמו מכיל תלמידים בדיוניים ותצוגות תפקיד בתוך חשבון המציג. הרשאות נפרדות לתלמיד ולמורה, כל סוגי הלומדות ושירות בינה מלאכותית מלא הם עבודת המשך.</p></section>`}
function render(){if(!localMode&&!session){loginScreen();return}if(route==='player'&&runtime)return;const pages={dashboard,library,assignments,learn,reports,'my-results':reports,insights:insightsPage,development,pipeline,environments,guide};if(!pages[route])route=state.role==='student'?'learn':'dashboard';shell(pages[route]())}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function exportCsv(){const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const rows=allSummaries().filter(x=>state.role!=='student'||x.user.id===state.learner);download('ofek-learning-report.csv','\ufeff'+[['תלמיד','לומדה','מצב','ציון','שאלות','נכונות','שגויות'],...rows.map(x=>[x.user.name,x.course.title,statusLabel(x.summary.status),x.summary.score,x.summary.questions,x.summary.correct,x.summary.wrong])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8')}
function simAction(action){const t=selectedTicket();if(!t)return;if(!readyTicket(t)){toast('צריך להשלים את הטיקט לפני פיתוח',true);return}let text='';if(action==='sim-review'){t.review='changes-requested';text='הסקירה המדומה מצאה: חסרה בדיקה לשמירה שנכשלה.'}if(action==='sim-fix'){bumpRevision(t);t.fixApplied=true;text='תוקנה התקלה בדוגמה. אישורים ישנים בוטלו.'}if(action==='sim-approve'){if(!t.fixApplied){toast('בדוגמה הזו יש לתקן קודם את ממצא הסקירה',true);return}t.review='approved';t.reviewRevision=t.revision;t.peer=true;t.peerRevision=t.revision;text='סקירה חוזרת ואישור עמית נרשמו בהדמיה.'}if(['sim-tests','sim-low'].includes(action)){t.tests='passed';t.testsRevision=t.revision;const n=action==='sim-low'?89:94;t.coverage={frontend:{lines:n,branches:n,functions:n},server:{lines:96,branches:92,functions:95}};text=`בדיקות מדומות עברו. כיסוי ${n}% בממשק ${n<90?'חוסם פריסה.':'עומד בסף.'}`}if(action==='sim-change'){bumpRevision(t);text='הקוד השתנה; כל אישורי הגרסה הקודמת בוטלו.'}if(action==='sim-stage'){if(!canStage(t))return;t.stagedRevision=t.revision;t.status='staging';state.environments.staging=`${t.id}-v${t.revision}`;text='הגרסה עברה לסביבת בדיקות מדומה.'}if(action==='sim-manual'){if(t.stagedRevision!==t.revision)return;t.manual='passed';t.manualRevision=t.revision;text='אושרה בדיקה ידנית מדומה לגרסה הזו.'}if(action==='sim-release-approve'){if(t.manualRevision!==t.revision)return;t.releaseApproval=true;text='נרשם אישור שחרור מדומה.'}if(action==='sim-release'){if(!canRelease(t))return;t.status='done';state.environments.production=`${t.id}-v${t.revision}`;text='השחרור המדומה הושלם אחרי כל שערי האיכות.'}state.runs.unshift({at:new Date().toISOString(),text});audit(text);persist();render()}
function loginScreen(error=''){$('#app').innerHTML=`<main class="login-page"><section class="login-story"><div class="brand"><div class="brand-mark">א</div><div class="brand-name">אופק</div></div><h1>כל לומד.<br>והדרך שלו.</h1><p>לומדה מוכנה הופכת לחוויית למידה — עם התקדמות, תוצאות ותובנות שאפשר להבין.</p><div class="login-steps"><span>01 · לומדים</span><span>02 · מודדים</span><span>03 · מבינים</span></div></section><section class="login-form"><div class="eyebrow">מערכת הדגמה לפגישת הצוות</div><h2>נכנסים לאופק</h2><p>חשבון מציג עם תלמידים בדיוניים. הנתונים נשמרים ב־Supabase.</p><form id="login-form"><label class="field">דואר אלקטרוני<input name="email" type="email" autocomplete="username" dir="ltr" required></label><label class="field">סיסמה<input name="password" type="password" autocomplete="current-password" dir="ltr" required></label><p class="error-text" role="alert">${esc(error)}</p><button class="btn" type="submit">כניסה למערכת ${icon('arrow')}</button></form><details><summary>הדגמה מקומית ללא חשבון</summary><p class="note">הנתונים יישמרו רק בדפדפן הזה, ללא Supabase.</p>${btn('פתיחת הדגמה מקומית','local-mode','secondary')}</details></section></main>`}
async function loadState(){try{let stored;if(localMode)stored=JSON.parse(localStorage.getItem(cacheKey())||'null')?.state;else {const remote=await cloudRequest('GET');stored=remote.state;const cached=JSON.parse(localStorage.getItem(cacheKey())||'null');if(cached?.pending&&cached.state){stored=cached.state;setTimeout(()=>{toast('שוחזרו שינויים מקומיים שטרם נשמרו בענן');persist()},100)}}if(stored)state={...baseState(),...stored};cloudStatus='saved';route=location.hash.slice(1)||'dashboard';render()}catch(e){cloudStatus='error';loginScreen('לא ניתן לטעון את הנתונים מהענן. '+e.message)}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;try{if(a.startsWith('sim-')){simAction(a);return}if(a==='close-modal')closeModal();if(a==='import-modal')importModal();if(a==='import')await importCourse(el.dataset.course);if(a==='assign')assignModal(el.dataset.course);if(a==='nav-library')goto('library');if(a==='teacher')switchRole('teacher');if(a==='launch')launch(el.dataset.course);if(a==='exit-course'){stopCourse();goto('learn')}if(a==='course-next')$('#course-frame').contentWindow.doNext();if(a==='course-prev')$('#course-frame').contentWindow.doPrevious();if(a==='course-quiz'){const w=$('#course-frame').contentWindow;w.currentPage=w.pageArray.length-1;w.goToPage()}if(a==='report')reportModal(el.dataset.course,el.dataset.user);if(a==='export-csv')exportCsv();if(a==='export-attempt'&&selectedReport)download('ofek-attempt.json',JSON.stringify(selectedReport,null,2));if(a==='course-info'){const c=course(el.dataset.course);modal('התוכן מגיע מוכן',c.title,`<p>זו חבילה רשמית של Rustici ללימוד גולף. היא פועלת בתוך המערכת ומדווחת לפי תקן SCORM.</p><p>${c.hasInteractions?'החבילה הזו מדווחת גם תשובות לשאלות ומטרות למידה.':'החבילה הזו מדווחת ציון והשלמה בלבד.'}</p><p>המקור אינו Storyline, אך הוא מדגים את תקן התקשורת שבו גם לומדות Storyline יכולות להשתמש. כל חבילת Storyline נוספת צריכה בדיקת תאימות.</p>${external(c.sourceUrl||'https://scorm.com/scorm-explained/technical-scorm/golf-examples/','מקור הדוגמה וההסבר')}`)}if(a==='new-ticket'){const t=createTicket(state.tickets.length+1);state.tickets.push(t);persist();ticketModal(t.id)}if(a==='ticket')ticketModal(el.dataset.id);if(a==='fill-ticket'){const f=$('#ticket-form');const values={title:'שמירת נקודת העצירה של התלמיד',description:'כשיוצאים מהלומדה וחוזרים, הלמידה ממשיכה מהמסך האחרון שנשמר.',acceptance:'לאחר יציאה במסך 4 וכניסה מחדש, הלומדה מציעה להמשיך מאותו מסך. כשל שמירה מוצג בבירור.',autoPlan:'בדיקת שמירת מיקום, טעינה חוזרת, טיפול בכשל וחסימת גישה ללא התחברות.',manualPlan:'להפעיל לומדה, להתקדם, לצאת, לחזור ולבדוק שהמיקום נשמר.'};Object.entries(values).forEach(([k,v])=>f.elements[k].value=v)}if(a==='guide-nav'){if(el.dataset.route==='learn')switchRole('noa');else{state.role='teacher';goto(el.dataset.route)}}if(a==='local-mode'){localMode=true;state=baseState();await loadState()}if(a==='logout'){stopCourse();await flush();await logout();localMode=false;state=baseState();loginScreen()}if(a==='mobile-nav')$('.sidebar').classList.toggle('open');if(a==='about')modal('מה עובד במערכת ההדגמה?','הפרדה ברורה בין מערכת פעילה לבין תכנון העבודה.',`<div class="insight good"><h4>פועל בפועל</h4><p>כניסה דרך Supabase, שמירת נתונים במסד רלציוני, שתי לומדות SCORM מקוריות, שיוך, הפעלה, התקדמות, דוחות ותובנות לפי כללים. Jira מכיל את משימות הפרויקט וקוד הפרויקט נמצא ב־GitHub.</p></div><div class="insight info"><h4>הדמיה והמשך פיתוח</h4><p>תצוגות המורה והתלמיד הן בתוך חשבון המציג. מעבדת הפיתוח, אישורי הסקירה, שלוש הסביבות והמתגים הם הדמיה. אין מנוע בינה מלאכותית מחובר ואין הבטחת תמיכה בכל חבילת SCORM.</p></div>`)}catch(err){toast(err.message||'הפעולה לא הושלמה',true)}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='login-form'){const b=f.querySelector('button');b.disabled=true;b.textContent='מתחבר…';try{await login(d.get('email'),d.get('password'));localMode=false;await loadState()}catch(err){loginScreen(err.message)}}if(f.id==='assignment-form'){const users=d.getAll('student');if(!users.length){toast('יש לבחור לפחות תלמיד אחד',true);return}let n=0;users.forEach(u=>{if(!state.assignments.some(x=>x.courseId===d.get('course')&&x.userId===u)){state.assignments.push({id:uid(),courseId:d.get('course'),userId:u,due:d.get('due'),assignedAt:new Date().toISOString()});n++}});audit(`הלומדה שויכה ל־${n} תלמידים`,'learning');persist();closeModal();goto('assignments');toast(`נשמרו ${n} שיוכים חדשים`)}if(f.id==='ticket-form'){const t=state.tickets.find(x=>x.id===f.dataset.id);if(t.status!=='draft')bumpRevision(t);['title','description','acceptance','owner','tester','autoPlan','manualPlan'].forEach(k=>t[k]=d.get(k).trim());t.status='development';audit(`הוגדר טיקט הדגמה ${t.id}`);persist();closeModal();goto('development')}});
document.addEventListener('change',async e=>{if(e.target.id==='package-file'&&e.target.files[0])await importCourse(null,e.target.files[0]);if(e.target.id==='pipeline-ticket'){state.selectedTicket=e.target.value;persist();render()}if(e.target.dataset.flag){const {flag,env}=e.target.dataset;if(env==='production'&&e.target.checked&&!state.tickets.some(t=>canRelease(t)&&t.status==='done')){e.target.checked=false;toast('בהדמיה, הפעלה למשתמשים דורשת שחרור מאושר',true);return}state.flags[flag][env]=e.target.checked;audit(`מתג ${flag} בסביבת ${env}: ${e.target.checked?'פעיל':'כבוי'} (הדמיה)`);persist()}});
window.addEventListener('hashchange',()=>{if(runtime)stopCourse();route=location.hash.slice(1)||'dashboard';render();scrollTo(0,0)});window.addEventListener('beforeunload',()=>{if(runtime)stopCourse()});
try{[catalog,questionLabels]=await Promise.all(['./samples/catalog.json','./samples/question-labels.json'].map(async u=>(await fetch(u)).json()));if(session)await loadState();else loginScreen()}catch(e){$('#app').innerHTML='<main class="main"><h1>לא ניתן לטעון את המערכת</h1><p>נסו לרענן את העמוד.</p></main>';console.error(e)}
